ad137efc-82be-461a-871e-f51afbac63ed	392e146e-92d3-486c-a4f3-efa54a628127	93493eab-9453-434d-98e6-f51a75e913a0	live_move_2_d6d6c1b6	move	goal_frame	\N	{"id": "live_move_2_d6d6c1b6", "type": "goal_frame", "phase": "opening", "title": "Learning goal: Integration by parts (7 minutes)", "blockId": "live_block_2_2c48fb14", "content": "{\\"schemaVersion\\":\\"petros.render.v2\\",\\"title\\":\\"Learning goal: Integration by parts (7 minutes)\\",\\"type\\":\\"goal_frame\\",\\"goal\\":\\"In the next 7 minutes, you'll state a clear, timeboxed learning outcome for Integration by parts: explain the integration-by-parts formula and use it to evaluate one integral; then agree to the immediate practice plan (one worked example followed by a short practice question).\\",\\"timeEstimateMinutes\\":7,\\"checkpoints\\":[\\"Student repeats or accepts the one-sentence learning outcome.\\",\\"Student agrees to the practice plan: worked example then one practice question.\\",\\"Ready to begin the worked example now.\\"]}", "startedAtMs": 30988, "completedAtMs": 30988, "sourceAnchors": [], "decisionFactors": ["Topic profile opening pattern: after prerequisite_check the next move should be goal_frame", "Short remaining time budget — keep the goal statement brief and actionable", "Student persona repeated_struggle — explicit goal and plan reduce confusion and help focus"], "artifactProposed": false, "expectedEvidence": "Student repeats or accepts a concise, timeboxed learning outcome (one sentence) and agrees to the immediate practice format (worked example followed by a short practice question).", "firstContentAtMs": 30988, "studentSafeReason": "Frame a short, timeboxed learning goal so the student knows the immediate outcome and next steps after the prerequisite check.", "studentConsentRequired": false}	2026-08-09 18:35:00.905796+03
